window.repoFiles={"content": {"akce": {"2015-10-17.json": {"content": "{\n  \"title\": \"Brigáda na nádvoří\",\n  \"date\": \"2015-10-17\",\n  \"text\": \"Úprava nádvoří, čištění náletů a novinky o dalším osudu zámku.\",\n  \"photos\": [\n    \"img/akce/2015-10-17-1.jpg\",\n    \"img/akce/2015-10-17-2.jpg\"\n  ]\n}"}, "2016-08-13.json": {"content": "{\n  \"title\": \"Workshop - výroba ptačích budek a krmítek\",\n  \"date\": \"2016-08-13\",\n  \"text\": \"Na zámeckém nádvoří účastníci vyráběli ze zbytkového dřeva ptačí budky a krmítka zdobená klacíky a přírodními materiály. Vznikly dvě budky, z toho jedna pro netopýry, a jedno krmítko.\",\n  \"photos\": [\n    \"img/akce/2016-08-13-1.jpg\",\n    \"img/akce/2016-08-13-2.jpg\",\n    \"img/akce/2016-08-13-3.jpg\",\n    \"img/akce/2016-08-13-4.jpg\"\n  ]\n}"}, "2023-06-28.json": {"content": "{\n  \"title\": \"Stužkování žáků 9. tříd ZŠ Toužim\",\n  \"date\": \"2023-06-28\",\n  \"text\": \"Žáci všech tří devátých tříd toužimské základní školy u nás se svými učiteli slavnostně zakončili studium.\",\n  \"photos\": [\n    \"img/akce/2023-06-28-1.jpg\",\n    \"img/akce/2023-06-28-2.jpg\",\n    \"img/akce/2023-06-28-3.jpg\",\n    \"img/akce/2023-06-28-4.jpg\"\n  ]\n}"}, "2017-07-15.json": {"content": "{\n  \"title\": \"Festival na zámku 2017 (1. ročník)\",\n  \"date\": \"2017-07-15\"\n}"}, "2023-06-23.json": {"content": "{\n  \"title\": \"Svatojánské slavnosti\",\n  \"date\": \"2023-06-23\"\n}"}, "2024-06-15.json": {"content": "{\n  \"title\": \"Festival na zámku, 8. ročník\",\n  \"date\": \"2024-06-15\",\n  \"text\": \"Rockový festival na nádvoří, který od roku 2017 pořádá Kalimero Agency. Občerstvení zajistila Hospůdka U Havlů.\",\n  \"photos\": [\n    \"img/akce/2024-06-15-1.jpg\",\n    \"img/akce/2024-06-15-2.jpg\",\n    \"img/akce/2024-06-15-3.jpg\",\n    \"img/akce/2024-06-15-4.jpg\"\n  ]\n}"}, "2026-03-21.json": {"content": "{\n  \"title\": \"Zámecká hostina\",\n  \"date\": \"2026-03-21\",\n  \"text\": \"První ze série zámeckých hostin v Horním zámku. Setkání pro všechny, kterým zámek není lhostejný: co bychom na zámku rádi viděli a kdo se chce zapojit.\",\n  \"poster\": \"img/plakaty/2026_hostina.jpg\",\n  \"photos\": [\n    \"img/akce/2026-03-21-1.jpg\"\n  ]\n}"}, "2021-06-05.json": {"content": "{\n  \"title\": \"Dětský den\",\n  \"date\": \"2021-06-05\",\n  \"text\": \"Navzdory nepříznivé předpovědi přišla spousta lidí; proběhly soutěže, hry, tanečky a vyrábění. Vše završila Tibetská pohádka Divadla loutek Karlovy Vary.\",\n  \"poster\": \"img/plakaty/2021_gp_06-05.jpg\"\n}"}, "2018-07-06.json": {"content": "{\n  \"title\": \"Den mistra Jana Husa v Toužimi\",\n  \"date\": \"2018-07-06\"\n}"}, "2021-10-09-cce.json": {"content": "{\n  \"title\": \"Community Celebration Event na zámku Toužim\",\n  \"date\": \"2021-10-09\",\n  \"when\": \"sobota · 14:30\",\n  \"text\": \"Community celebration event k dvacetiletému výročí geocachingu s prohlídkou zámku a koncertem středověké hudby.\"\n}"}, "2024-06-29.json": {"content": "{\n  \"title\": \"Den města: 555 let Toužimi\",\n  \"date\": \"2024-06-29\",\n  \"text\": \"Oslava 555 let od povýšení Toužimi na město. Šerm Alia Tempora, tanečnice Shahinez, hudba Cavalla Canor, kovář, včelař, tvořivé dílny, hry Jiřího Šebesty na zahradě a pohádky Poutníka Hrocha.\",\n  \"photos\": [\n    \"img/akce/2024-06-29-1.jpg\",\n    \"img/akce/2024-06-29-2.jpg\",\n    \"img/akce/2024-06-29-3.jpg\",\n    \"img/akce/2024-06-29-4.jpg\",\n    \"img/akce/2024-06-29-5.jpg\",\n    \"img/akce/2024-06-29-6.jpg\"\n  ]\n}"}, "2022-03-26.json": {"content": "{\n  \"title\": \"Jarní brigádička\",\n  \"date\": \"2022-03-26\",\n  \"text\": \"Jarní úklid zámeckého areálu s občerstvením pro pomocníky.\",\n  \"photos\": [\n    \"img/akce/2022-03-26-1.jpg\",\n    \"img/akce/2022-03-26-2.jpg\"\n  ]\n}"}, "2017-08-12.json": {"content": "{\n  \"title\": \"Perseidy na zámku\",\n  \"date\": \"2017-08-12\"\n}"}, "2026-07-26.json": {"content": "{\n  \"title\": \"Ranní vinyasa joga\",\n  \"date\": \"2026-07-26\",\n  \"when\": \"neděle · 8:45\",\n  \"text\": \"Ranní vinyasa jógu s Reginou Pavlíčkovou jsme cvičili na zámeckém nádvoří.\",\n  \"photos\": [\n    \"img/akce/2026-07-26-1.jpg\"\n  ]\n}"}, "2024-10-26.json": {"content": "{\n  \"title\": \"Halloween na zámku\",\n  \"date\": \"2024-10-26\",\n  \"text\": \"Strašisklepení a Bubu komnata, malování na obličej, hry, dílnička a lampionový průvod. Poprvé i večerní netradiční prohlídky.\",\n  \"poster\": \"img/plakaty/2024_gp_10-26.jpg\",\n  \"photos\": [\n    \"img/akce/2024-10-26-1.jpg\",\n    \"img/akce/2024-10-26-2.jpg\",\n    \"img/akce/2024-10-26-3.jpg\",\n    \"img/akce/2024-10-26-4.jpg\",\n    \"img/akce/2024-10-26-5.jpg\",\n    \"img/akce/2024-10-26-6.jpg\",\n    \"img/akce/2024-10-26-7.jpg\",\n    \"img/akce/2024-10-26-8.jpg\"\n  ]\n}"}, "2024-05-18-toulky.json": {"content": "{\n  \"title\": \"Toulky krajem s Jean de Carrem\",\n  \"date\": \"2024-05-18\",\n  \"text\": \"Vystoupení Jeana de Carra na závěr jarní brigády.\"\n}"}, "2020-07-11.json": {"content": "{\n  \"title\": \"Pokládání podlahy v hradní komnatě\",\n  \"date\": \"2020-07-11\",\n  \"end\": \"2020-07-12\",\n  \"text\": \"Brigáda na novou podlahu v první hradní komnatě – v sobotu se hoblovalo a pokládalo od devíti ráno do deseti večer, v neděli se pokračovalo až do odpoledne. Na práci se podíleli Michal Nedvídek, Jakub Červený a Hanz Policar.\",\n  \"photos\": [\n    \"img/akce/2020-07-11-1.jpg\",\n    \"img/akce/2020-07-11-2.jpg\",\n    \"img/akce/2020-07-11-3.jpg\",\n    \"img/akce/2020-07-11-4.jpg\"\n  ]\n}"}, "2023-06-20.json": {"content": "{\n  \"title\": \"Zámecká tajenka pro základní školy\",\n  \"date\": \"2023-06-20\",\n  \"text\": \"Zámecká tajenka pro třídy místních základních škol, připravená ve spolupráci s Infocentrem Toužim; děti byly pozorné a zvídavé.\"\n}"}, "2026-07-10.json": {"content": "{\n  \"title\": \"Hudební večer s Milanem Pitkinem a Františkem Nedvědem\",\n  \"date\": \"2026-07-10\",\n  \"text\": \"Večer s příhodami Milana Pitkina a písničkami Františka Nedvěda na podporu spolku. Pořádala Arabela Agency.\",\n  \"poster\": \"img/plakaty/2026_hudebni_vecer_charita.jpg\",\n  \"photos\": [\n    \"img/akce/2026-07-10-1.jpg\",\n    \"img/akce/2026-07-10-2.jpg\",\n    \"img/akce/2026-07-10-3.jpg\"\n  ]\n}"}, "2026-10-17.json": {"content": "{\n  \"title\": \"XVII. Zámecké CITO a Poznej & pomoz\",\n  \"date\": \"2026-10-17\",\n  \"end\": \"2026-10-18\",\n  \"when\": \"so 10–16 · ne 10–17\",\n  \"short\": \"Sobota: úklid okolí zámku a pomoc se zahradou, hraje Longway. Neděle: plecí brigáda na svahu pro dětské prvky.\",\n  \"text\": \"**Sobota 17. 10., 10:00–16:00: XVII. Zámecké CITO.** Uklidíme prostor v okolí zámku a hlavně pomůžeme ve výstavbě zámecké zahrady. Mini výstava věnovaná geocachingu, eventová CWG za 10 Kč. Celý den hraje zámecká kapela Longway.\\n**Neděle 18. 10., 10:00–17:00: Zámecká plecí brigáda Poznej &amp; pomoz.** Pomozte s úklidem svahu pro dětské prvky a posuňme společně zámeckou zahradu o krok dál.\\nObčerstvení zajištěno po oba dny: guláš, buřty, klobásy, pečivo, káva, čaj, pivo a limo.\",\n  \"poster\": \"img/plakaty/2026_cito_17_10.jpg\",\n  \"tag\": \"Přijďte pomoct\"\n}"}, "2022-05-28.json": {"content": "{\n  \"title\": \"Dětský den na zámku Toužim\",\n  \"date\": \"2022-05-28\",\n  \"when\": \"sobota · 13:00\",\n  \"text\": \"Dětský den se soutěžemi o ceny, ukázkami lesnických řemesel od Lesů ČR – lesní správy Toužim a hromadou pěny od SDH Toužim.\",\n  \"poster\": \"img/plakaty/2022_gp_05-28.jpg\",\n  \"photos\": [\n    \"img/akce/2022-05-28-1.jpg\",\n    \"img/akce/2022-05-28-2.jpg\",\n    \"img/akce/2022-05-28-3.jpg\",\n    \"img/akce/2022-05-28-4.jpg\"\n  ]\n}"}, "2018-10-13.json": {"content": "{\n  \"title\": \"Podzimní brigáda a Zámecké CITO\",\n  \"date\": \"2018-10-13\",\n  \"text\": \"Brigáda v rámci projektu 72 hodin spojená s CITO eventem geocacherů: hrabání listí a vysekávání náletů.\"\n}"}, "2016-04-02.json": {"content": "{\n  \"title\": \"Brigáda na zámku\",\n  \"date\": \"2016-04-02\",\n  \"text\": \"Brigáda byla zaměřená na zvelebení nádvoří zámku pro toužimskou veřejnost; dobrovolníci zablokovali vchody z nádvoří do nebezpečných budov zámku, což je podmínkou města pro veřejné využití nádvoří.\"\n}"}, "2026-07-25.json": {"content": "{\n  \"title\": \"Zámecký jarmark\",\n  \"date\": \"2026-07-25\",\n  \"text\": \"Řemeslné stánky a ukázky: kovář, soustružení dřevěných misek, krajkářka, vinuté perly, med, chleba z kvásku, porcelán a jedlé rostliny. Odpoledne pohádka Ochotníků Ostrov, hrál Pedro. V neděli ráno jóga na nádvoří.\",\n  \"poster\": \"img/plakaty/2026_jarmark.jpg\",\n  \"photos\": [\n    \"img/akce/2026-07-25-1.jpg\",\n    \"img/akce/2026-07-25-2.jpg\",\n    \"img/akce/2026-07-25-3.jpg\",\n    \"img/akce/2026-07-25-4.jpg\"\n  ]\n}"}, "2017-12-09.json": {"content": "{\n  \"title\": \"Vánoční setkání se svařákem\",\n  \"date\": \"2017-12-09\"\n}"}, "2018-09-08.json": {"content": "{\n  \"title\": \"Punkovice na zámku\",\n  \"date\": \"2018-09-08\",\n  \"text\": \"Hráli Plusmlíko, Stamp Out System, Prasex, Já Ještě Nevim a ŠpuntQaně. Dorazilo přes 200 návštěvníků.\",\n  \"poster\": \"img/plakaty/2018_punkovice.jpg\"\n}"}, "2017-07-06.json": {"content": "{\n  \"title\": \"Program na zámku 2017\",\n  \"date\": \"2017-07-06\",\n  \"poster\": \"img/plakaty/2017_zzt_program.jpg\",\n  \"titleTodo\": true\n}"}, "2026-09-12.json": {"content": "{\n  \"title\": \"Punkovice, 9. ročník\",\n  \"date\": \"2026-09-12\",\n  \"text\": \"Hráli Výblitek (místo KT Bandits), Vypitý lahváče, ŠpuntQaně, Plesnivý fazole a P.U.M. Podepsaný plakát se vydražil za 1 000 Kč.\",\n  \"poster\": \"img/plakaty/2026_punkovice.jpg\",\n  \"photos\": [\n    \"img/akce/2026-09-12-1.jpg\"\n  ]\n}"}, "2017-03-26.json": {"content": "{\n  \"title\": \"Jarní brigádička\",\n  \"date\": \"2017-03-26\",\n  \"text\": \"První jarní brigáda roku: hrabání listí a úklid nádvoří.\",\n  \"photos\": [\n    \"img/akce/2017-03-26-1.jpg\",\n    \"img/akce/2017-03-26-2.jpg\"\n  ]\n}"}, "2024-05-02.json": {"content": "{\n  \"title\": \"Brigáda\",\n  \"date\": \"2024-05-02\",\n  \"photos\": [\n    \"img/akce/2024-05-02-1.jpg\",\n    \"img/akce/2024-05-02-2.jpg\"\n  ],\n  \"titleTodo\": true\n}"}, "2023-07-15.json": {"content": "{\n  \"title\": \"Dětské odpoledne s divadlem Jitule & Dadule\",\n  \"date\": \"2023-07-15\",\n  \"text\": \"Pohádka O perníkové chaloupce divadla Jitule a Dadule a tematické hry.\",\n  \"poster\": \"img/plakaty/2023_gp_07-15.jpg\",\n  \"photos\": [\n    \"img/akce/2023-07-15-1.jpg\",\n    \"img/akce/2023-07-15-2.jpg\",\n    \"img/akce/2023-07-15-3.jpg\",\n    \"img/akce/2023-07-15-4.jpg\"\n  ]\n}"}, "2023-06-24.json": {"content": "{\n  \"title\": \"Historické odpoledne a výstava obrazů z puzzlí\",\n  \"date\": \"2023-06-24\",\n  \"end\": \"2023-07-30\",\n  \"text\": \"Den města s dobovou hudbou Cavalla Canor, šermem Alia Tempora, tanečnicemi Shahinez, Evou a flašinetem a kovářskou výhní. V komnatách začala výstava obrazů z puzzlí Jana Policara, otevřená do 30. 7.\",\n  \"poster\": \"img/plakaty/2023_vystava_plakat.jpg\",\n  \"photos\": [\n    \"img/akce/2023-06-24-1.jpg\",\n    \"img/akce/2023-06-24-2.jpg\",\n    \"img/akce/2023-06-24-3.jpg\",\n    \"img/akce/2023-06-24-4.jpg\"\n  ]\n}"}, "2023-06-17.json": {"content": "{\n  \"title\": \"Festival na zámku 2023 (7. ročník)\",\n  \"date\": \"2023-06-17\",\n  \"when\": \"sobota · 14:00\",\n  \"text\": \"Sedmý ročník festivalu se nesl v téměř rodinné atmosféře. Zahráli Cerberos Heavy Rock, Seven, Roxor a Fata Morgana.\",\n  \"poster\": \"img/plakaty/2023_gp_06-17.jpg\",\n  \"photos\": [\n    \"img/akce/2023-06-17-1.jpg\",\n    \"img/akce/2023-06-17-2.jpg\",\n    \"img/akce/2023-06-17-3.jpg\",\n    \"img/akce/2023-06-17-4.jpg\"\n  ]\n}"}, "2016-12-10.json": {"content": "{\n  \"title\": \"Vánoční setkání se svařákem\",\n  \"date\": \"2016-12-10\"\n}"}, "2017-09-05.json": {"content": "{\n  \"title\": \"Ve sklepení a interiérech zámku\",\n  \"date\": \"2017-09-05\",\n  \"photos\": [\n    \"img/akce/2017-09-05-1.jpg\",\n    \"img/akce/2017-09-05-2.jpg\",\n    \"img/akce/2017-09-05-3.jpg\",\n    \"img/akce/2017-09-05-4.jpg\"\n  ],\n  \"titleTodo\": true\n}"}, "2020-09-12.json": {"content": "{\n  \"title\": \"Historický den - založení města Toužim (551 let)\",\n  \"date\": \"2020-09-12\",\n  \"text\": \"Historické odpoledne k 551. výročí založení Toužimi s vystoupením dobové hudby Cavalla Canor, šermířského souboru Zlatý Grál, tanečnice Shahinez a Evy s flašinetem. Vrcholem bylo slavnostní otevření nové komnaty s výstavou sbírky 130 výtisků knihy Babička od Boženy Němcové.\"\n}"}, "2018-06-23.json": {"content": "{\n  \"title\": \"Svatojánské slavnosti\",\n  \"date\": \"2018-06-23\"\n}"}, "2022-08-13.json": {"content": "{\n  \"title\": \"Punkovice 2022\",\n  \"date\": \"2022-08-13\",\n  \"text\": \"Hráli Stamp Out System, Porucha systému, Čekišó, Vypitý lahváče, Já ještě nevim a ŠpuntQaně.\",\n  \"poster\": \"img/plakaty/2022_gp_08-13.jpg\",\n  \"photos\": [\n    \"img/akce/2022-08-13-1.jpg\",\n    \"img/akce/2022-08-13-2.jpg\",\n    \"img/akce/2022-08-13-3.jpg\",\n    \"img/akce/2022-08-13-4.jpg\"\n  ]\n}"}, "2024-04-30.json": {"content": "{\n  \"title\": \"Pálení čarodějnic\",\n  \"date\": \"2024-04-30\",\n  \"text\": \"Stavění máje na náměstí s orchestrem ZUŠ Toužim, potom výroba čarodějnice a vatra na zámeckém nádvoří. Pořádáme společně s SDH Toužim.\",\n  \"poster\": \"img/plakaty/2024_gp_04-30.jpg\",\n  \"photos\": [\n    \"img/akce/2024-04-30-1.jpg\",\n    \"img/akce/2024-04-30-2.jpg\",\n    \"img/akce/2024-04-30-3.jpg\"\n  ]\n}"}, "2017-03-17.json": {"content": "{\n  \"title\": \"Brigáda\",\n  \"date\": \"2017-03-17\",\n  \"photos\": [\n    \"img/akce/2017-03-17-1.jpg\",\n    \"img/akce/2017-03-17-2.jpg\",\n    \"img/akce/2017-03-17-3.jpg\"\n  ],\n  \"titleTodo\": true\n}"}, "2022-07-23.json": {"content": "{\n  \"title\": \"Kolem světa - cestovatel Kompásek\",\n  \"date\": \"2022-07-23\",\n  \"text\": \"Cestovatel Kompásek provedl děti celým světem a zavedl je až k lidojedům.\",\n  \"poster\": \"img/plakaty/2022_gp_07-23.jpg\",\n  \"photos\": [\n    \"img/akce/2022-07-23-1.jpg\",\n    \"img/akce/2022-07-23-2.jpg\",\n    \"img/akce/2022-07-23-3.jpg\",\n    \"img/akce/2022-07-23-4.jpg\"\n  ]\n}"}, "2025-05-17.json": {"content": "{\n  \"title\": \"Community Celebration Event: jarní CITO 2025\",\n  \"date\": \"2025-05-17\",\n  \"when\": \"sobota · 11:30\",\n  \"text\": \"Geocacheři osadili infotabuli, vyčistili pódium, uklidili místnost s krbem, natřeli stoly do zámecké kavárny a upravili ohniště. Hráli Cavalla Canor a Longway, Castra Romana předvedla římskou bitvu a proběhla předpremiéra filmu o zámku.\",\n  \"photos\": [\n    \"img/akce/2025-05-17-1.jpg\"\n  ]\n}"}, "2025-08-23.json": {"content": "{\n  \"title\": \"Hradozámecká noc\",\n  \"date\": \"2025-08-23\",\n  \"text\": \"Poprvé jsme se zapojili do Hradozámecké noci Národního památkového ústavu. Večerní prohlídky zámkem při svíčkách se setkáním s Černým mnichem a zámeckým pánem. Všechny prohlídky byly vyprodané, přišlo 45 lidí.\",\n  \"poster\": \"img/plakaty/2025_hzn_plakat_a2_bezorez.jpg\",\n  \"photos\": [\n    \"img/akce/2025-08-23-1.jpg\",\n    \"img/akce/2025-08-23-2.jpg\",\n    \"img/akce/2025-08-23-3.jpg\",\n    \"img/akce/2025-08-23-4.jpg\",\n    \"img/akce/2025-08-23-5.jpg\",\n    \"img/akce/2025-08-23-6.jpg\"\n  ]\n}"}, "2016-09-17.json": {"content": "{\n  \"title\": \"Koncert skupiny Cerberos a výtvarné odpoledne\",\n  \"date\": \"2016-09-17\"\n}"}, "2018-08-18.json": {"content": "{\n  \"title\": \"Letní kino: Loupež za bílého dne\",\n  \"date\": \"2018-08-18\",\n  \"poster\": \"img/plakaty/2018_letni_kino.jpg\"\n}"}, "2023-09-09.json": {"content": "{\n  \"title\": \"Punkovice 2023\",\n  \"date\": \"2023-09-09\",\n  \"text\": \"Hráli Znouzectnost, ŠpuntQaně, Stamp Out System, ADHD Helmut, Vypitý lahváče a Adult Misery. Rekordní návštěvnost, akce roku.\",\n  \"poster\": \"img/plakaty/2023_punkovice.jpg\",\n  \"photos\": [\n    \"img/akce/2023-09-09-1.jpg\",\n    \"img/akce/2023-09-09-2.jpg\",\n    \"img/akce/2023-09-09-3.jpg\",\n    \"img/akce/2023-09-09-4.jpg\"\n  ]\n}"}, "2025-12-14.json": {"content": "{\n  \"title\": \"Vánoční setkání\",\n  \"date\": \"2025-12-14\",\n  \"text\": \"Zdobení stromečku, dílnička CVČ Kačaba, stezka vánočních zvyků, soutěž o nejlepší vánočku, pohádka Ochotníků z Ostrova a koledy se ZUŠ Toužim.\",\n  \"poster\": \"img/plakaty/2025_vanoce.jpg\",\n  \"photos\": [\n    \"img/akce/2025-12-14-1.jpg\",\n    \"img/akce/2025-12-14-2.jpg\",\n    \"img/akce/2025-12-14-3.jpg\",\n    \"img/akce/2025-12-14-4.jpg\"\n  ]\n}"}, "2016-10-15.json": {"content": "{\n  \"title\": \"72 hodin na zámku Toužim\",\n  \"date\": \"2016-10-15\"\n}"}, "2026-04-30.json": {"content": "{\n  \"title\": \"Pálení čarodějnic a stavění máje\",\n  \"date\": \"2026-04-30\",\n  \"poster\": \"img/plakaty/2026_carodejnice_a4.jpg\",\n  \"photos\": [\n    \"img/akce/2026-04-30-1.jpg\",\n    \"img/akce/2026-04-30-2.jpg\"\n  ]\n}"}, "2018-06-09.json": {"content": "{\n  \"title\": \"Dětský den\",\n  \"date\": \"2018-06-09\",\n  \"when\": \"sobota · 13:00\",\n  \"text\": \"Podle plakátu: dětský den s Divadlem poutníka Hrocha (pohádky Údolí klapajících mlýnků a Jak tovaryš zachránil království), tvořivou dílnou a soutěžemi pro děti.\"\n}"}, "2021-11-06.json": {"content": "{\n  \"title\": \"Halloween na zámku\",\n  \"date\": \"2021-11-06\",\n  \"text\": \"Odpoledne plné sluníčka a zábavy – podávaly se domácí perníčky a muffiny, vyrábělo se v tvořivých dílnách, plnily se úkoly ve společnosti mladých čarodějek a strašilo se v hradním sklepení. O akci pak psal i deník Právo.\",\n  \"poster\": \"img/plakaty/2021_gp_11-06.jpg\",\n  \"photos\": [\n    \"img/akce/2021-11-06-1.jpg\",\n    \"img/akce/2021-11-06-2.jpg\",\n    \"img/akce/2021-11-06-3.jpg\",\n    \"img/akce/2021-11-06-4.jpg\"\n  ]\n}"}, "2026-05-16.json": {"content": "{\n  \"title\": \"Zámecké CITO, jarní\",\n  \"date\": \"2026-05-16\",\n  \"end\": \"2026-05-17\",\n  \"text\": \"XVI. Zámecké CITO a v neděli první brigáda Poznej & pomoz. Vyklidila se většina plochy pod hradbou a vznikl růžový záhon podél zámecké zdi. Odpoledne zazněly balady a pověsti Jeana de Carra.\",\n  \"poster\": \"img/plakaty/2026_poznej_pomoz_16_5_cito.jpg\",\n  \"photos\": [\n    \"img/akce/2026-05-16-1.jpg\",\n    \"img/akce/2026-05-16-2.jpg\",\n    \"img/akce/2026-05-16-3.jpg\",\n    \"img/akce/2026-05-16-4.jpg\"\n  ]\n}"}, "2022-10-15.json": {"content": "{\n  \"title\": \"Zámecké CITO, podzim 2022\",\n  \"date\": \"2022-10-15\",\n  \"text\": \"Jubilejní desátá dobrovolnická brigáda v rámci projektu 72 hodin. Hrála kapela Longway.\",\n  \"photos\": [\n    \"img/akce/2022-10-15-1.jpg\",\n    \"img/akce/2022-10-15-2.jpg\",\n    \"img/akce/2022-10-15-3.jpg\"\n  ]\n}"}, "2023-07-29.json": {"content": "{\n  \"title\": \"Zámecký jarmark\",\n  \"date\": \"2023-07-29\",\n  \"when\": \"sobota · 10:00–18:00\",\n  \"text\": \"Jarmark na nádvoří i přes nepříznivé počasí přilákal hodně návštěvníků.\",\n  \"poster\": \"img/plakaty/2023_gp_07-29.jpg\",\n  \"photos\": [\n    \"img/akce/2023-07-29-1.jpg\",\n    \"img/akce/2023-07-29-2.jpg\",\n    \"img/akce/2023-07-29-3.jpg\",\n    \"img/akce/2023-07-29-4.jpg\"\n  ]\n}"}, "2017-07-08.json": {"content": "{\n  \"title\": \"Historické odpoledne na zámku Toužim\",\n  \"date\": \"2017-07-08\"\n}"}, "2026-05-30.json": {"content": "{\n  \"title\": \"Den dětí na palubě\",\n  \"date\": \"2026-05-30\",\n  \"text\": \"Pirátský den dětí: stezka s úkoly, program s CVČ Kačaba a královnou Pipi, vystoupení ZUŠ Toužim, stanoviště Lesů ČR a pěna od SDH Toužim. V zámku začala výstava dětských prací.\",\n  \"poster\": \"img/plakaty/2026_dd.jpg\",\n  \"photos\": [\n    \"img/akce/2026-05-30-1.jpg\",\n    \"img/akce/2026-05-30-2.jpg\",\n    \"img/akce/2026-05-30-3.jpg\",\n    \"img/akce/2026-05-30-4.jpg\"\n  ]\n}"}, "2017-08-26.json": {"content": "{\n  \"title\": \"Letní kino\",\n  \"date\": \"2017-08-26\"\n}"}, "2025-09-06.json": {"content": "{\n  \"title\": \"Divadlo na zámku\",\n  \"date\": \"2025-09-06\",\n  \"text\": \"Druhý divadelní den: pohádky Krejčík hrdina (Divadélko Ondřej) a O Palečkovi (Jitule a Dadule), bublinová show a večer hra Nevěrníci divadla MAEBH.\",\n  \"poster\": \"img/plakaty/2025_divadlo_na_zamku.jpg\",\n  \"photos\": [\n    \"img/akce/2025-09-06-1.jpg\",\n    \"img/akce/2025-09-06-2.jpg\",\n    \"img/akce/2025-09-06-3.jpg\",\n    \"img/akce/2025-09-06-4.jpg\"\n  ]\n}"}, "2019-05-25.json": {"content": "{\n  \"title\": \"Zámecké CITO Toužim 2019 - Jaro\",\n  \"date\": \"2019-05-25\"\n}"}, "2026-06-27.json": {"content": "{\n  \"title\": \"Historický den, 557 let města\",\n  \"date\": \"2026-06-27\",\n  \"text\": \"Oslava 557 let města: pohádka O Karkulákovi (Jitule a Dadule), Cavalla Canor, Eva a flašinet, šerm Alia Tempora, římské ležení Castra Romana, Poutník Hroch jako mistr popravčí, chůdaři SHŠ Lorika a řemeslné stánky. Návštěvníci přispěli na zahradu přes 3 000 Kč.\",\n  \"poster\": \"img/plakaty/2026_historicky_den.jpg\"\n}"}, "2018-07-21.json": {"content": "{\n  \"title\": \"Festival na zámku 2018 (2. ročník)\",\n  \"date\": \"2018-07-21\"\n}"}, "2017-05-20.json": {"content": "{\n  \"title\": \"Zámecké CITO Toužim 2017 - Jaro\",\n  \"date\": \"2017-05-20\"\n}"}, "2022-12-17.json": {"content": "{\n  \"title\": \"Vánoční setkání a zámecký betlém\",\n  \"date\": \"2022-12-17\",\n  \"text\": \"Návštěvníci přinesli postavičky sebe a svých rodin a společně jsme zalidnili zámecký betlém.\",\n  \"poster\": \"img/plakaty/2022_gp_12-17.jpg\",\n  \"photos\": [\n    \"img/akce/2022-12-17-1.jpg\"\n  ]\n}"}, "2022-05-21.json": {"content": "{\n  \"title\": \"Zámecké CITO, jaro 2022\",\n  \"date\": \"2022-05-21\",\n  \"text\": \"První CITO po převzetí štafety od Dílny U mnicha: úklid nádvoří, řezání a pálení náletů, hrabání listí.\",\n  \"poster\": \"img/plakaty/2022_gp_05-21.jpg\",\n  \"photos\": [\n    \"img/akce/2022-05-21-1.jpg\"\n  ]\n}"}, "2025-08-02.json": {"content": "{\n  \"title\": \"Pelmel muziky\",\n  \"date\": \"2025-08-02\",\n  \"text\": \"Hudební odpoledne s ukázkami country tanců.\",\n  \"poster\": \"img/plakaty/2025_pelmel_muziky.jpg\",\n  \"photos\": [\n    \"img/akce/2025-08-02-1.jpg\",\n    \"img/akce/2025-08-02-2.jpg\",\n    \"img/akce/2025-08-02-3.jpg\",\n    \"img/akce/2025-08-02-4.jpg\"\n  ]\n}"}, "2024-08-31.json": {"content": "{\n  \"title\": \"Punkovice 2024\",\n  \"date\": \"2024-08-31\",\n  \"poster\": \"img/plakaty/2024_punkovice.jpg\",\n  \"photos\": [\n    \"img/akce/2024-08-31-1.jpg\",\n    \"img/akce/2024-08-31-2.jpg\",\n    \"img/akce/2024-08-31-3.jpg\",\n    \"img/akce/2024-08-31-4.jpg\"\n  ]\n}"}, "2026-06-20.json": {"content": "{\n  \"title\": \"Rockový festival, 10. ročník\",\n  \"date\": \"2026-06-20\",\n  \"text\": \"Jubilejní 10. ročník benefičního rockového festivalu. Hráli mimo jiné De Bill Heads, Corona, PfP rock a Fata Morgana, která tu oslavila 40 let a pokřtila nové album.\",\n  \"photos\": [\n    \"img/akce/2026-06-20-1.jpg\"\n  ]\n}"}, "2025-04-30.json": {"content": "{\n  \"title\": \"Pálení čarodějnic a stavění máje\",\n  \"date\": \"2025-04-30\",\n  \"text\": \"Stavění máje a vatra se třemi čarodějnicemi, které vyrobily děti z kroužků CVČ Kačaba.\",\n  \"poster\": \"img/plakaty/2025_carodejnice_a3.jpg\",\n  \"photos\": [\n    \"img/akce/2025-04-30-1.jpg\",\n    \"img/akce/2025-04-30-2.jpg\",\n    \"img/akce/2025-04-30-3.jpg\",\n    \"img/akce/2025-04-30-4.jpg\"\n  ]\n}"}, "2019-04-30.json": {"content": "{\n  \"title\": \"Pálení čarodějnic\",\n  \"date\": \"2019-04-30\",\n  \"poster\": \"img/plakaty/2019_palenicarodejnic.jpg\",\n  \"photos\": [\n    \"img/akce/2019-04-30-1.jpg\",\n    \"img/akce/2019-04-30-2.jpg\"\n  ]\n}"}, "2016-07-02.json": {"content": "{\n  \"title\": \"Tvořivý víkend na zámku\",\n  \"date\": \"2016-07-02\",\n  \"end\": \"2016-07-03\",\n  \"text\": \"Sobota: zkrášlovací brigáda, dobrovolníci vítáni. Neděle: tvorba šperků a ozdob pro děti i dospělé, sousedské občerstvení.\",\n  \"poster\": \"img/plakaty/2016_zivy_zamek_plakat.jpg\"\n}"}, "2020-07-25.json": {"content": "{\n  \"title\": \"Pohádkové odpoledne s Culinkou\",\n  \"date\": \"2020-07-25\",\n  \"text\": \"Hudebně-pohybový pořad Culinka a tancohrátky, pohádkové prohlídky hradu s úkoly, malování na obličej a písková dílnička.\",\n  \"photos\": [\n    \"img/akce/2020-07-25-1.jpg\",\n    \"img/akce/2020-07-25-2.jpg\",\n    \"img/akce/2020-07-25-3.jpg\",\n    \"img/akce/2020-07-25-4.jpg\"\n  ]\n}"}, "2020-08-15.json": {"content": "{\n  \"title\": \"Punkovice na zámku (3. ročník)\",\n  \"date\": \"2020-08-15\",\n  \"photos\": [\n    \"img/akce/2020-08-15-1.jpg\"\n  ]\n}"}, "2023-10-14.json": {"content": "{\n  \"title\": \"Zámecké CITO, podzim 2023\",\n  \"date\": \"2023-10-14\",\n  \"text\": \"Dvanácté CITO: vyřezání náletů, úklid areálu a odměnou komentovaná prohlídka.\"\n}"}, "2022-07-30.json": {"content": "{\n  \"title\": \"Zámecký Flerjarmark\",\n  \"date\": \"2022-07-30\",\n  \"text\": \"Jarmark se stánky a živou hudbou kapely Longway, která nám darovala vypalovanou desku s naším logem. Počet vystavujících a prodávajících byl rekordní.\",\n  \"photos\": [\n    \"img/akce/2022-07-30-1.jpg\",\n    \"img/akce/2022-07-30-2.jpg\",\n    \"img/akce/2022-07-30-3.jpg\",\n    \"img/akce/2022-07-30-4.jpg\"\n  ]\n}"}, "2026-08-21.json": {"content": "{\n  \"title\": \"Letní kino: Po večeřce\",\n  \"date\": \"2026-08-21\",\n  \"text\": \"Promítání české komedie Po večerce. Kvůli dešti se promítalo v konírně.\",\n  \"poster\": \"img/plakaty/2026_letni_kino.jpg\",\n  \"photos\": [\n    \"img/akce/2026-08-21-1.jpg\",\n    \"img/akce/2026-08-21-2.jpg\"\n  ]\n}"}, "2026-08-08.json": {"content": "{\n  \"title\": \"Pelmel muziky\",\n  \"date\": \"2026-08-08\",\n  \"text\": \"Druhý ročník letního hudebního odpoledne: St. Johnny, Country Pocket a večer u ohně s Pájou Jančou a Dámou s hranostajem.\",\n  \"poster\": \"img/plakaty/2026_pelmel_a3.jpg\",\n  \"photos\": [\n    \"img/akce/2026-08-08-1.jpg\",\n    \"img/akce/2026-08-08-2.jpg\",\n    \"img/akce/2026-08-08-3.jpg\",\n    \"img/akce/2026-08-08-4.jpg\"\n  ]\n}"}, "2021-08-21.json": {"content": "{\n  \"title\": \"Punkovice na zámku (4. ročník)\",\n  \"date\": \"2021-08-21\",\n  \"text\": \"Další ročník punkového mejdanu na zámku, kde kapely zahrály a návštěvníci zapařili.\",\n  \"poster\": \"img/plakaty/2021_gp_08-21.jpg\",\n  \"photos\": [\n    \"img/akce/2021-08-21-1.jpg\"\n  ]\n}"}, "2020-07-18.json": {"content": "{\n  \"title\": \"Country fest na zámku (1. ročník)\",\n  \"date\": \"2020-07-18\",\n  \"text\": \"První ročník hudební akce v duchu country & folk, doplněný malým jarmarkem s tradičními rukodělnými výrobky. Počasí vyšlo parádně.\"\n}"}, "2019-06-28.json": {"content": "{\n  \"title\": \"Oslavy 550 let založení města Toužim\",\n  \"date\": \"2019-06-28\",\n  \"end\": \"2019-06-30\"\n}"}, "2026-09-26-oslava.json": {"content": "{\n  \"title\": \"Oslava 10 let spolku Živý zámek Toužim\",\n  \"date\": \"2026-09-26\",\n  \"text\": \"Odpoledne zahradní brigády patřilo oslavě 10 let činnosti spolku – s dortem, hudebním doprovodem Pedra a předáním listin čestným členům zámecké družiny. Večer jsme poseděli u ohně s kytarou; během dne navíc vznikla první zámecká květinová školka.\"\n}"}, "2017-07-28.json": {"content": "{\n  \"title\": \"Letní kino\",\n  \"date\": \"2017-07-28\"\n}"}, "2023-05-20.json": {"content": "{\n  \"title\": \"Zámecké CITO, jaro 2023\",\n  \"date\": \"2023-05-20\",\n  \"text\": \"Jedenácté CITO: vyřezání náletů a oživení zámecké skalky. Hrála kapela Longway.\",\n  \"poster\": \"img/plakaty/2023_gp_05-20.jpg\",\n  \"photos\": [\n    \"img/akce/2023-05-20-1.jpg\",\n    \"img/akce/2023-05-20-2.jpg\",\n    \"img/akce/2023-05-20-3.jpg\",\n    \"img/akce/2023-05-20-4.jpg\"\n  ]\n}"}, "2023-04-30.json": {"content": "{\n  \"title\": \"Pálení čarodějnic\",\n  \"date\": \"2023-04-30\",\n  \"text\": \"Při pálení čarodějnice zahrála kapela Dáma s hranostajem.\",\n  \"poster\": \"img/plakaty/2023_gp_04-30.jpg\",\n  \"photos\": [\n    \"img/akce/2023-04-30-1.jpg\",\n    \"img/akce/2023-04-30-2.jpg\",\n    \"img/akce/2023-04-30-3.jpg\",\n    \"img/akce/2023-04-30-4.jpg\"\n  ]\n}"}, "2016-05-28.json": {"content": "{\n  \"title\": \"Brigáda na zámku\",\n  \"date\": \"2016-05-28\",\n  \"text\": \"Podle pozvánky byla v plánu brigáda od 10 hodin: čištění pódia a hlediště a příprava na letní akce.\"\n}"}, "2026-09-26.json": {"content": "{\n  \"title\": \"Poznej & pomoz: brigáda na zámku\",\n  \"date\": \"2026-09-26\",\n  \"end\": \"2026-09-28\",\n  \"text\": \"Další zahradní brigáda během Dnů evropského dědictví. Vznikla první zámecká květinová školka a v sobotu jsme oslavili 10 let činnosti spolku.\",\n  \"poster\": \"img/plakaty/2026_poznej_pomoz_26_28_9.jpg\",\n  \"photos\": [\n    \"img/akce/2026-09-26-1.jpg\",\n    \"img/akce/2026-09-26-2.jpg\",\n    \"img/akce/2026-09-26-3.jpg\",\n    \"img/akce/2026-09-26-4.jpg\"\n  ]\n}"}, "2022-06-11.json": {"content": "{\n  \"title\": \"Festival na zámku, 6. ročník\",\n  \"date\": \"2022-06-11\",\n  \"text\": \"Rockový festival na nádvoří. Hráli Cerberos, Loretta, Hlahol a Fata Morgana.\",\n  \"poster\": \"img/plakaty/2022_gp_06-11.jpg\",\n  \"photos\": [\n    \"img/akce/2022-06-11-1.jpg\",\n    \"img/akce/2022-06-11-2.jpg\",\n    \"img/akce/2022-06-11-3.jpg\",\n    \"img/akce/2022-06-11-4.jpg\"\n  ]\n}"}, "2021-08-14.json": {"content": "{\n  \"title\": \"Dětské odpoledne s divadlem loutek Karlovy Vary\",\n  \"date\": \"2021-08-14\",\n  \"text\": \"Děti zhlédly pohádku Duhový princ Divadla loutek Karlovy Vary a rodiče si prohlédli výstavu.\",\n  \"photos\": [\n    \"img/akce/2021-08-14-1.jpg\",\n    \"img/akce/2021-08-14-2.jpg\",\n    \"img/akce/2021-08-14-3.jpg\",\n    \"img/akce/2021-08-14-4.jpg\"\n  ]\n}"}, "2026-12-13.json": {"content": "{\n  \"title\": \"Vánoční setkání se svařákem\",\n  \"date\": \"2026-12-13\",\n  \"when\": \"neděle\",\n  \"short\": \"Tradiční konec sezóny na nádvoří se svařákem.\",\n  \"tag\": \"Pro všechny\"\n}"}, "2026-10-25.json": {"content": "{\n  \"title\": \"Dětská brigáda: hrabání listí\",\n  \"date\": \"2026-10-25\",\n  \"when\": \"neděle · 14:00\",\n  \"short\": \"Děti nahrabou haldu listí, do které se pak na Halloween skáče z pódia. Hrábě jsou připravené.\",\n  \"text\": \"Mimořádná brigáda pro děti. Chcete zase tu skvělou haldu listí, do které se dá na Halloween skákat z pódia? Přijďte ji nahrabat! Sraz ve 14:00 u brány zámku, hrábě jsou připravené a na účastníky čeká malé překvapení.\",\n  \"poster\": \"img/plakaty/2026_hrabani_listi.jpg\",\n  \"tag\": \"Pro děti\"\n}"}, "2018-12-15.json": {"content": "{\n  \"title\": \"Vánoční setkání\",\n  \"date\": \"2018-12-15\",\n  \"text\": \"Setkání u svařáku s pečenými čaji, marmeládami a upomínkovými předměty na podporu zastřešení pódia.\",\n  \"photos\": [\n    \"img/akce/2018-12-15-1.jpg\",\n    \"img/akce/2018-12-15-2.jpg\"\n  ]\n}"}, "2019-08-24.json": {"content": "{\n  \"title\": \"Stavba zastřešení pódia\",\n  \"date\": \"2019-08-24\",\n  \"text\": \"Dobrovolníci v létě 2019 postavili dřevěné zastřešení pódia na nádvoří.\",\n  \"photos\": [\n    \"img/akce/2019-08-24-1.jpg\",\n    \"img/akce/2019-08-24-2.jpg\",\n    \"img/akce/2019-08-24-3.jpg\",\n    \"img/akce/2019-08-24-4.jpg\",\n    \"img/akce/2019-08-24-5.jpg\",\n    \"img/akce/2019-08-24-6.jpg\"\n  ]\n}"}, "2019-06-08.json": {"content": "{\n  \"title\": \"Dětský den\",\n  \"date\": \"2019-06-08\"\n}"}, "2025-11-08.json": {"content": "{\n  \"title\": \"Halloween po páté na zámku\",\n  \"date\": \"2025-11-08\",\n  \"text\": \"Pátý zámecký Halloween: stezka úkolů, strašidelně vyzdobený hrad, hmatová stanoviště a dílničky CVČ Kačaba, strašidelné tanečky a lampionový průvod.\",\n  \"poster\": \"img/plakaty/2025_halloween.jpg\",\n  \"photos\": [\n    \"img/akce/2025-11-08-1.jpg\",\n    \"img/akce/2025-11-08-2.jpg\",\n    \"img/akce/2025-11-08-3.jpg\",\n    \"img/akce/2025-11-08-4.jpg\"\n  ]\n}"}, "2017-04-30.json": {"content": "{\n  \"title\": \"Stavění májky a pálení čarodějnic\",\n  \"date\": \"2017-04-30\"\n}"}, "2024-12-14.json": {"content": "{\n  \"title\": \"Vánoční setkání na zámku\",\n  \"date\": \"2024-12-14\",\n  \"text\": \"Koledy, svařák, tvořivá dílna pro děti, taneční vystoupení a soutěž o nejlepší perníčky a rohlíčky.\",\n  \"poster\": \"img/plakaty/2024_gp_12-14.jpg\",\n  \"photos\": [\n    \"img/akce/2024-12-14-1.jpg\",\n    \"img/akce/2024-12-14-2.jpg\",\n    \"img/akce/2024-12-14-3.jpg\",\n    \"img/akce/2024-12-14-4.jpg\"\n  ]\n}"}, "2016-07-08.json": {"content": "{\n  \"title\": \"Den města Toužimi\",\n  \"date\": \"2016-07-08\",\n  \"poster\": \"img/plakaty/2016_dmh_dmt_zamek.jpg\"\n}"}, "2026-04-25.json": {"content": "{\n  \"title\": \"Dny dobrovolnictví\",\n  \"date\": \"2026-04-25\",\n  \"end\": \"2026-04-26\",\n  \"text\": \"Jarní úklid a pomoc se zámeckou zahradou. Za víkend se vyklidila asi pětina terasy, připravila vatra na čarodějnice, vyčistilo pódium a připravilo sociální zázemí. Hrála kapela Longway, guláš uvařila Hospůdka U Havlů.\",\n  \"poster\": \"img/plakaty/2026_dny_dobrovolnictvi.jpg\",\n  \"photos\": [\n    \"img/akce/2026-04-25-1.jpg\",\n    \"img/akce/2026-04-25-2.jpg\",\n    \"img/akce/2026-04-25-3.jpg\",\n    \"img/akce/2026-04-25-4.jpg\"\n  ]\n}"}, "2017-10-14.json": {"content": "{\n  \"title\": \"Zámecké CITO Toužim 2017 - Podzim\",\n  \"date\": \"2017-10-14\"\n}"}, "2020-05-30.json": {"content": "{\n  \"title\": \"Dětský den\",\n  \"date\": \"2020-05-30\"\n}"}, "2019-04-06.json": {"content": "{\n  \"title\": \"Ukliďme Česko - brigáda\",\n  \"date\": \"2019-04-06\"\n}"}, "2025-05-31.json": {"content": "{\n  \"title\": \"Dětský den\",\n  \"date\": \"2025-05-31\",\n  \"text\": \"Soutěže pro malé i větší děti s odměnou za splněné úkoly, stanoviště Lesů ČR. Pomáhaly CVČ Kačaba a ZUŠ Toužim.\",\n  \"poster\": \"img/plakaty/2025_detsky_den.jpg\",\n  \"photos\": [\n    \"img/akce/2025-05-31-1.jpg\",\n    \"img/akce/2025-05-31-2.jpg\",\n    \"img/akce/2025-05-31-3.jpg\",\n    \"img/akce/2025-05-31-4.jpg\"\n  ]\n}"}, "2021-06-12.json": {"content": "{\n  \"title\": \"Festival na zámku 2021 (5. ročník)\",\n  \"date\": \"2021-06-12\",\n  \"text\": \"Jubilejní pátý ročník Rockfestu s rekordní návštěvou přes 400 lidí. Zahráli Cerberos Heavy Rock, Rimortis, Kreyson Memorial a Carpatia Castle.\",\n  \"photos\": [\n    \"img/akce/2021-06-12-1.jpg\",\n    \"img/akce/2021-06-12-2.jpg\",\n    \"img/akce/2021-06-12-3.jpg\"\n  ]\n}"}, "2021-07-10.json": {"content": "{\n  \"title\": \"Historické odpoledne, 552 let města\",\n  \"date\": \"2021-07-10\",\n  \"text\": \"Pohádka divadla Kamila, Cavalla Canor, tanečnice Shahinez, šerm Zlatý Grál a Duellanti, Eva a flašinet, historický průvod a odhalení nové informační cedule. Večer koncert Dámy s hranostajem a výstava k 5. výročí spolku.\",\n  \"photos\": [\n    \"img/akce/2021-07-10-1.jpg\",\n    \"img/akce/2021-07-10-2.jpg\",\n    \"img/akce/2021-07-10-3.jpg\",\n    \"img/akce/2021-07-10-4.jpg\"\n  ]\n}"}, "2025-07-26.json": {"content": "{\n  \"title\": \"Zámecký jarmark\",\n  \"date\": \"2025-07-26\",\n  \"text\": \"Řemeslné stánky, ukázka pečení chleba, kynoložka, stánek Maminy s rakovinou a sestřičky z Domácí zdravotní péče Toužim. Hrála kapela Longway.\",\n  \"poster\": \"img/plakaty/2025_jarmark.jpg\",\n  \"photos\": [\n    \"img/akce/2025-07-26-1.jpg\",\n    \"img/akce/2025-07-26-2.jpg\",\n    \"img/akce/2025-07-26-3.jpg\",\n    \"img/akce/2025-07-26-4.jpg\"\n  ]\n}"}, "2015-12-12.json": {"content": "{\n  \"title\": \"Vánoční setkání na zámku se svařákem\",\n  \"date\": \"2015-12-12\",\n  \"text\": \"První adventní setkání na zámeckém nádvoří se svařákem a koledami.\",\n  \"poster\": \"img/plakaty/2016_vanocni_setkani.jpg\"\n}"}, "2016-01-26.json": {"content": "{\n  \"title\": \"Přednáška Obrazy ze života jednoho zámku\",\n  \"date\": \"2016-01-26\",\n  \"text\": \"Přednáška o dějinách a stavebním vývoji zámku v Infocentru Toužim.\"\n}"}, "2016-04-30.json": {"content": "{\n  \"title\": \"Brigáda a první pálení čarodějnic\",\n  \"date\": \"2016-04-30\",\n  \"text\": \"Stavba plotu, čištění hlediště, pálení náletů a první čarodějnice na zámku.\"\n}"}, "2019-10-12.json": {"content": "{\n  \"title\": \"Zámecké CITO Toužim 2019 - Podzim\",\n  \"date\": \"2019-10-12\"\n}"}, "2019-04-27.json": {"content": "{\n  \"title\": \"Slet čarodějnic\",\n  \"date\": \"2019-04-27\",\n  \"text\": \"Odpoledne jsme si vyrobili čarodějnice a zabavili se.\",\n  \"poster\": \"img/plakaty/2019_palenicarodejnic.jpg\",\n  \"photos\": [\n    \"img/akce/2019-04-27-1.jpg\",\n    \"img/akce/2019-04-27-2.jpg\",\n    \"img/akce/2019-04-27-3.jpg\",\n    \"img/akce/2019-04-27-4.jpg\"\n  ]\n}"}, "2022-11-05.json": {"content": "{\n  \"title\": \"Halloween na zámku\",\n  \"date\": \"2022-11-05\",\n  \"text\": \"Halloween s tvořivými dílnami, psaním husím brkem, strašidelným sklepením a lampionovým průvodem. Největší úspěch ale měla hromada spadaného listí.\",\n  \"poster\": \"img/plakaty/2022_gp_11-05.jpg\",\n  \"photos\": [\n    \"img/akce/2022-11-05-1.jpg\",\n    \"img/akce/2022-11-05-2.jpg\",\n    \"img/akce/2022-11-05-3.jpg\",\n    \"img/akce/2022-11-05-4.jpg\"\n  ]\n}"}, "2026-09-05.json": {"content": "{\n  \"title\": \"Divadlo na zámku: Dívčí válka\",\n  \"date\": \"2026-09-05\",\n  \"text\": \"Třetí divadelní den: pohádka Rytíř a Ošklivá dáma (Divadélko Ondřej), bublinová show Jitule a Dadule a večer Dívčí válka s F. R. Čechem. S finanční podporou města Toužim.\",\n  \"poster\": \"img/plakaty/2026_divci_valka_a3.jpg\",\n  \"photos\": [\n    \"img/akce/2026-09-05-1.jpg\",\n    \"img/akce/2026-09-05-2.jpg\",\n    \"img/akce/2026-09-05-3.jpg\",\n    \"img/akce/2026-09-05-4.jpg\"\n  ]\n}"}, "2017-09-16.json": {"content": "{\n  \"title\": \"Toužimský minifest na zámku\",\n  \"date\": \"2017-09-16\"\n}"}, "2018-07-28.json": {"content": "{\n  \"title\": \"Letní kino: Špunti na vodě\",\n  \"date\": \"2018-07-28\",\n  \"text\": \"Promítání rodinné komedie Špunti na vodě na nádvoří.\",\n  \"poster\": \"img/plakaty/2018_letni_kino.jpg\"\n}"}, "2022-09-10.json": {"content": "{\n  \"title\": \"Dny evropského dědictví 2022\",\n  \"date\": \"2022-09-10\"\n}"}, "2021-09-12.json": {"content": "{\n  \"title\": \"Toužimské léto\",\n  \"date\": \"2021-09-12\",\n  \"text\": \"Rozloučení s létem na zámeckém nádvoří – hrála muzika, točilo se pivo a podávaly se klobásy.\",\n  \"photos\": [\n    \"img/akce/2021-09-12-1.jpg\",\n    \"img/akce/2021-09-12-2.jpg\"\n  ]\n}"}, "2018-07-07.json": {"content": "{\n  \"title\": \"Historické odpoledne na zámku Toužim\",\n  \"date\": \"2018-07-07\"\n}"}, "2021-10-09.json": {"content": "{\n  \"title\": \"Zámecké CITO Toužim 2021 - Podzim\",\n  \"date\": \"2021-10-09\",\n  \"when\": \"sobota · 11:00\",\n  \"text\": \"Podzimní CITO přilákalo tolik lidí, že padl historický rekord v návštěvnosti, a udělalo se víc práce, než bylo v plánu. Poděkování patří také Dílně U mnicha.\",\n  \"photos\": [\n    \"img/akce/2021-10-09-1.jpg\",\n    \"img/akce/2021-10-09-2.jpg\",\n    \"img/akce/2021-10-09-3.jpg\",\n    \"img/akce/2021-10-09-4.jpg\"\n  ]\n}"}, "2025-06-28.json": {"content": "{\n  \"title\": \"Historický den\",\n  \"date\": \"2025-06-28\",\n  \"text\": \"Oslava 556 let města: divadlo Jitule a Dadule, Eva a flašinet, Cavalla Canor, Jean de Carro, tanečnice Shahinez, šerm Castra Romana a Alia Tempora, kováři, chůdaři a řemeslné stánky. Premiéra filmu o toužimském zámku od MiRo film.\",\n  \"poster\": \"img/plakaty/2025_historicky_den.jpg\",\n  \"photos\": [\n    \"img/akce/2025-06-28-1.jpg\",\n    \"img/akce/2025-06-28-2.jpg\",\n    \"img/akce/2025-06-28-3.jpg\",\n    \"img/akce/2025-06-28-4.jpg\"\n  ]\n}"}, "2017-06-04.json": {"content": "{\n  \"title\": \"Dětský den\",\n  \"date\": \"2017-06-04\",\n  \"text\": \"První dětský den na zámku. Ráno hrozilo počasí, odpoledne vylezlo sluníčko.\"\n}"}, "2026-03-30.json": {"content": "{\n  \"title\": \"Začátek prací na zámecké zahradě\",\n  \"date\": \"2026-03-30\",\n  \"end\": \"2026-04-04\",\n  \"text\": \"Minibagr, pařezy ven a první terénní úpravy. Při pracích jsme narazili na původní hradební zeď.\",\n  \"photos\": [\n    \"img/akce/2026-03-30-1.jpg\",\n    \"img/akce/2026-03-30-2.jpg\",\n    \"img/akce/2026-03-30-3.jpg\",\n    \"img/akce/2026-03-30-4.jpg\",\n    \"img/akce/2026-03-30-5.jpg\",\n    \"img/akce/2026-03-30-6.jpg\",\n    \"img/akce/2026-03-30-7.jpg\"\n  ]\n}"}, "2018-07-08.json": {"content": "{\n  \"title\": \"Den města Toužim\",\n  \"date\": \"2018-07-08\"\n}"}, "2026-08-16.json": {"content": "{\n  \"title\": \"Boj s plevelem na zámecké zahradě\",\n  \"date\": \"2026-08-16\",\n  \"end\": \"2026-09-06\",\n  \"text\": \"Plecí brigády 16. 8., 23. 8., 30. 8. a 6. 9. 2026.\",\n  \"poster\": \"img/plakaty/2026_boj_s_plevelem.jpg\",\n  \"photos\": [\n    \"img/akce/2026-08-16-1.jpg\",\n    \"img/akce/2026-08-16-2.jpg\",\n    \"img/akce/2026-08-16-3.jpg\",\n    \"img/akce/2026-08-16-4.jpg\"\n  ]\n}"}, "2023-06-03.json": {"content": "{\n  \"title\": \"Dětský den\",\n  \"date\": \"2023-06-03\",\n  \"text\": \"Soutěže o ceny, tvořivé dílny, pěna od hasičů SDH Toužim, řemeslné ukázky Lesů ČR a kapela Dáma s hranostajem.\",\n  \"poster\": \"img/plakaty/2023_dd_plakat.jpg\",\n  \"photos\": [\n    \"img/akce/2023-06-03-1.jpg\",\n    \"img/akce/2023-06-03-2.jpg\",\n    \"img/akce/2023-06-03-3.jpg\",\n    \"img/akce/2023-06-03-4.jpg\"\n  ]\n}"}, "2026-07-04.json": {"content": "{\n  \"title\": \"Paranormální jevy aneb fakt na zámku straší?\",\n  \"date\": \"2026-07-04\",\n  \"text\": \"Beseda o paranormálních jevech s Jitkou Lenkovou a Karlem Dudkem, přednáška Jana Husára o vyšetřování jevů a večerní ukázky vyšetřování v prostorách hradu.\",\n  \"poster\": \"img/plakaty/2026_ducharina.jpg\",\n  \"photos\": [\n    \"img/akce/2026-07-04-1.jpg\",\n    \"img/akce/2026-07-04-2.jpg\"\n  ]\n}"}, "2021-07-05.json": {"content": "{\n  \"title\": \"Brigáda\",\n  \"date\": \"2021-07-05\",\n  \"photos\": [\n    \"img/akce/2021-07-05-1.jpg\",\n    \"img/akce/2021-07-05-2.jpg\"\n  ],\n  \"titleTodo\": true\n}"}, "2020-06-20.json": {"content": "{\n  \"title\": \"Festival na zámku 2020 (4. ročník)\",\n  \"date\": \"2020-06-20\",\n  \"when\": \"sobota · 14:00\",\n  \"text\": \"Čtvrtý ročník zámeckého rockového festivalu se i přes nepřízeň počasí odehrál před zhruba stovkou fanoušků a kapely hrály jako o život. Večírek kolem půlnoci ukončila až policie.\",\n  \"photos\": [\n    \"img/akce/2020-06-20-1.jpg\",\n    \"img/akce/2020-06-20-2.jpg\"\n  ]\n}"}, "2021-07-31.json": {"content": "{\n  \"title\": \"Zámecký Flerjarmark\",\n  \"date\": \"2021-07-31\",\n  \"when\": \"sobota · 13:00\",\n  \"text\": \"Druhý ročník jarmarku s rukodělnými výrobky, šperky, ozdobami a občerstvením, hrami a vyráběním pro děti a komentovanými prohlídkami části hradu. Návštěvníci si mohli prohlédnout i nové zábradlí na baště.\",\n  \"poster\": \"img/plakaty/2021_gp_07-31.jpg\",\n  \"photos\": [\n    \"img/akce/2021-07-31-1.jpg\",\n    \"img/akce/2021-07-31-2.jpg\",\n    \"img/akce/2021-07-31-3.jpg\",\n    \"img/akce/2021-07-31-4.jpg\"\n  ]\n}"}, "2019-07-20.json": {"content": "{\n  \"title\": \"Festival na zámku 2019 (3. ročník)\",\n  \"date\": \"2019-07-20\",\n  \"photos\": [\n    \"img/akce/2019-07-20-1.jpg\",\n    \"img/akce/2019-07-20-2.jpg\",\n    \"img/akce/2019-07-20-3.jpg\",\n    \"img/akce/2019-07-20-4.jpg\",\n    \"img/akce/2019-07-20-5.jpg\"\n  ]\n}"}, "2023-11-04.json": {"content": "{\n  \"title\": \"Halloween na zámku\",\n  \"date\": \"2023-11-04\",\n  \"when\": \"sobota · 15:00–17:30\",\n  \"text\": \"Strašidelné sklepení, letos i s mlhovačem, nový fotokoutek a v 17:30 lampionový průvod.\",\n  \"poster\": \"img/plakaty/2023_gp_11-04.jpg\"\n}"}, "2016-03-07.json": {"content": "{\n  \"title\": \"Jarní úklid nádvoří\",\n  \"date\": \"2016-03-07\",\n  \"photos\": [\n    \"img/akce/2016-03-07-1.jpg\"\n  ],\n  \"titleTodo\": true\n}"}, "2026-08-22.json": {"content": "{\n  \"title\": \"Hradozámecká noc\",\n  \"date\": \"2026-08-22\",\n  \"text\": \"Večerní prohlídky zámkem při svíčkách s průvodci v kostýmech a hranými příběhy.\",\n  \"poster\": \"img/plakaty/2026_hzn_program_a2.jpg\",\n  \"photos\": [\n    \"img/akce/2026-08-22-1.jpg\",\n    \"img/akce/2026-08-22-2.jpg\",\n    \"img/akce/2026-08-22-3.jpg\",\n    \"img/akce/2026-08-22-4.jpg\"\n  ]\n}"}, "2025-06-21.json": {"content": "{\n  \"title\": \"Festival na zámku, 9. ročník\",\n  \"date\": \"2025-06-21\",\n  \"text\": \"Hráli Carpatia Castle, Krleš, Cerberos a Trojka.\",\n  \"photos\": [\n    \"img/akce/2025-06-21-1.jpg\",\n    \"img/akce/2025-06-21-2.jpg\",\n    \"img/akce/2025-06-21-3.jpg\",\n    \"img/akce/2025-06-21-4.jpg\"\n  ]\n}"}, "2018-05-19.json": {"content": "{\n  \"title\": \"Zámecké CITO Toužim 2018 - Jaro\",\n  \"date\": \"2018-05-19\"\n}"}, "2024-06-01.json": {"content": "{\n  \"title\": \"Dětský den\",\n  \"date\": \"2024-06-01\",\n  \"text\": \"Dětský den za každého počasí: soutěže, dílny a pěna od SDH Toužim, při dešti v útrobách zámku.\",\n  \"poster\": \"img/plakaty/2024_gp_06-01.jpg\",\n  \"photos\": [\n    \"img/akce/2024-06-01-1.jpg\",\n    \"img/akce/2024-06-01-2.jpg\",\n    \"img/akce/2024-06-01-3.jpg\",\n    \"img/akce/2024-06-01-4.jpg\"\n  ]\n}"}, "2024-07-27.json": {"content": "{\n  \"title\": \"Zámecký jarmark\",\n  \"date\": \"2024-07-27\",\n  \"when\": \"sobota · 10:00–17:00\",\n  \"text\": \"Na jarmarku byl stánkový prodej keramiky, výrobků ze dřeva, šperků a doplňků, občerstvení a káva. Celým dnem provázela živá hudba a hrálo se i divadlo.\",\n  \"poster\": \"img/plakaty/2024_gp_07-27.jpg\",\n  \"photos\": [\n    \"img/akce/2024-07-27-1.jpg\",\n    \"img/akce/2024-07-27-2.jpg\",\n    \"img/akce/2024-07-27-3.jpg\",\n    \"img/akce/2024-07-27-4.jpg\"\n  ]\n}"}, "2020-06-14.json": {"content": "{\n  \"title\": \"Zámecký Flerjarmark\",\n  \"date\": \"2020-06-14\",\n  \"when\": \"neděle · 13:00\",\n  \"text\": \"První zámecký Flerjarmark s rukodělnými výrobky přímo od autorů přilákal téměř plný počet stánkařů. Návštěvnost nakonec zhatila průtrž mračen, která všechny zahnala pod střechy.\"\n}"}, "2024-10-12.json": {"content": "{\n  \"title\": \"Zámecké CITO Toužim 2024 - Podzim\",\n  \"date\": \"2024-10-12\",\n  \"text\": \"Podle pozvánky: podzimní CITO event (VIII. ročník) v rámci projektu 72 hodin s hudebním doprovodem zámecké kapely Longway; děti mohly sbírat kaštany.\",\n  \"poster\": \"img/plakaty/2024_gp_10-12.jpg\"\n}"}, "2019-09-07.json": {"content": "{\n  \"title\": \"Punkovice na zámku (2. ročník)\",\n  \"date\": \"2019-09-07\",\n  \"text\": \"Druhý ročník Punkovic, na kterých na poslední chvíli potvrdil účast i soubor Špuntqaně.\"\n}"}, "2016-07-06.json": {"content": "{\n  \"title\": \"Den Mistra Jana Husa\",\n  \"date\": \"2016-07-06\",\n  \"poster\": \"img/plakaty/2016_dmh_dmt_zamek.jpg\"\n}"}, "2017-04-15.json": {"content": "{\n  \"title\": \"Úklid, čištění a příprava na čarodějnice\",\n  \"date\": \"2017-04-15\",\n  \"text\": \"Dobrovolníci navozili dřevo na hranici, popálili větve, vyřezali další nálety a natřeli první nový stůl.\"\n}"}, "2016-06-11.json": {"content": "{\n  \"title\": \"Perseidy: první zámecký koncert country kapely\",\n  \"date\": \"2016-06-11\",\n  \"text\": \"Vůbec první koncert na zámku. Hrála country kapela Perseidy, vstupné bylo dobrovolné.\",\n  \"poster\": \"img/plakaty/2016_zamek_plakat_06.jpg\",\n  \"photos\": [\n    \"img/akce/2016-06-11-1.jpg\",\n    \"img/akce/2016-06-11-2.jpg\",\n    \"img/akce/2016-06-11-3.jpg\"\n  ]\n}"}, "2026-10-31.json": {"content": "{\n  \"title\": \"Halloween na zámku\",\n  \"date\": \"2026-10-31\",\n  \"when\": \"sobota · 14:30–17:00\",\n  \"short\": \"Strašidelné sklepení, dílničky, lampionový průvod a soutěž o nejkrásnější dýni. Večer stezka pro dospělé.\",\n  \"text\": \"**14:30–17:00** strašidelné sklepení, Bubu komnata, dílničky a hry na nádvoří, malování na obličej.\\n**17:00** lampionový průvod městem, trasa přizpůsobená kočárkům.\\n**Soutěž o nejkrásnější vydlabanou dýni:** registrace do 16:30 u zámeckého pána, vyhlášení v 16:45.\\nNávštěvníci v maskách vítáni. Občerstvení zajištěno, vstupné dobrovolné.\\n**Letos mimořádně: halloweenská stezka pro dospělé od 18:30.** Registrace do 24. 10. na zivyzamektouzim@email.cz, vstupné 100 Kč. Není vhodná pro slabší povahy.\",\n  \"poster\": \"img/plakat-halloween-2026.jpg\",\n  \"tag\": \"Pro děti\"\n}"}, "2025-10-11.json": {"content": "{\n  \"title\": \"Zámecké CITO, podzimní brigáda\",\n  \"date\": \"2025-10-11\",\n  \"text\": \"XV. Zámecké CITO: vyčištěná dlažba, vyklizené sklepy a komnaty od kamení a suti, shrabané listí, odstraněné nálety a natřená infocedule. Hrála kapela Longway.\",\n  \"photos\": [\n    \"img/akce/2025-10-11-1.jpg\",\n    \"img/akce/2025-10-11-2.jpg\",\n    \"img/akce/2025-10-11-3.jpg\",\n    \"img/akce/2025-10-11-4.jpg\"\n  ]\n}"}, "2018-04-30.json": {"content": "{\n  \"title\": \"Pálení čarodějnic\",\n  \"date\": \"2018-04-30\",\n  \"photos\": [\n    \"img/akce/2018-04-30-1.jpg\"\n  ]\n}"}, "2018-09-15.json": {"content": "{\n  \"title\": \"Brigáda 31. skautského oddílu Vlaštovek z Plzně\",\n  \"date\": \"2018-09-15\",\n  \"end\": \"2018-09-16\",\n  \"photos\": [\n    \"img/akce/2018-09-15-1.jpg\",\n    \"img/akce/2018-09-15-2.jpg\",\n    \"img/akce/2018-09-15-3.jpg\",\n    \"img/akce/2018-09-15-4.jpg\",\n    \"img/akce/2018-09-15-5.jpg\",\n    \"img/akce/2018-09-15-6.jpg\"\n  ]\n}"}, "2022-04-30.json": {"content": "{\n  \"title\": \"Pálení čarodějnic\",\n  \"date\": \"2022-04-30\",\n  \"text\": \"Odpoledne výroba čarodějnic, po stavění máje vatra na nádvoří.\",\n  \"poster\": \"img/plakaty/2022_gp_04-30.jpg\",\n  \"photos\": [\n    \"img/akce/2022-04-30-1.jpg\",\n    \"img/akce/2022-04-30-2.jpg\",\n    \"img/akce/2022-04-30-3.jpg\",\n    \"img/akce/2022-04-30-4.jpg\"\n  ]\n}"}, "2022-06-25.json": {"content": "{\n  \"title\": \"Historický den - založení města Toužim (553 let)\",\n  \"date\": \"2022-06-25\",\n  \"text\": \"Historický den města s šermíři SHŠ Zlatý grál, tanečnicemi Shahinez, hudbou Cavalla Canor a Evy s flašinetem. Nechyběly sokolnické ukázky spolku TEIR a švihání bičem s Keltovinami.\",\n  \"poster\": \"img/plakaty/2022_gp_06-25.jpg\",\n  \"photos\": [\n    \"img/akce/2022-06-25-1.jpg\",\n    \"img/akce/2022-06-25-2.jpg\",\n    \"img/akce/2022-06-25-3.jpg\",\n    \"img/akce/2022-06-25-4.jpg\"\n  ]\n}"}, "2024-09-07.json": {"content": "{\n  \"title\": \"Divadelní den na zámku\",\n  \"date\": \"2024-09-07\",\n  \"text\": \"První ročník divadelního dne: dvě představení pro malé i velké, zámecká kavárna, fotokoutek, malování na obličej a dílničky.\",\n  \"poster\": \"img/plakaty/2024_gp_09-07.jpg\",\n  \"photos\": [\n    \"img/akce/2024-09-07-1.jpg\",\n    \"img/akce/2024-09-07-2.jpg\",\n    \"img/akce/2024-09-07-3.jpg\",\n    \"img/akce/2024-09-07-4.jpg\"\n  ]\n}"}, "2016-08-19.json": {"content": "{\n  \"title\": \"Koncert skupiny Moonpower\",\n  \"date\": \"2016-08-19\"\n}"}, "2023-12-16.json": {"content": "{\n  \"title\": \"Vánoční setkání se svařákem\",\n  \"date\": \"2023-12-16\",\n  \"poster\": \"img/plakaty/2023_gp_12-16.jpg\"\n}"}, "2020-07-03.json": {"content": "{\n  \"title\": \"Letní kino\",\n  \"date\": \"2020-07-03\"\n}"}, "2024-05-18.json": {"content": "{\n  \"title\": \"Zámecké CITO, jaro 2024\",\n  \"date\": \"2024-05-18\",\n  \"text\": \"Jarní brigáda zakončená vystoupením Jeana de Carra.\",\n  \"poster\": \"img/plakaty/2024_gp_05-18.jpg\",\n  \"photos\": [\n    \"img/akce/2024-05-18-1.jpg\",\n    \"img/akce/2024-05-18-2.jpg\",\n    \"img/akce/2024-05-18-3.jpg\",\n    \"img/akce/2024-05-18-4.jpg\"\n  ]\n}"}, "2025-07-04.json": {"content": "{\n  \"title\": \"Hudba u ohně\",\n  \"date\": \"2025-07-04\",\n  \"photos\": [\n    \"img/akce/2025-07-04-1.jpg\"\n  ],\n  \"titleTodo\": true\n}"}, "2019-12-15.json": {"content": "{\n  \"title\": \"Vánoční setkání se svařákem\",\n  \"date\": \"2019-12-15\"\n}"}, "2025-09-13.json": {"content": "{\n  \"title\": \"Punkovice 2025\",\n  \"date\": \"2025-09-13\",\n  \"text\": \"Punkový minifestival na nádvoří, hráli mimo jiné Vypitý lahváče, V.V.U. a Nízká Úroveň.\",\n  \"poster\": \"img/plakaty/2025_punkovice.jpg\",\n  \"photos\": [\n    \"img/akce/2025-09-13-1.jpg\",\n    \"img/akce/2025-09-13-2.jpg\",\n    \"img/akce/2025-09-13-3.jpg\",\n    \"img/akce/2025-09-13-4.jpg\"\n  ]\n}"}}, "web": {"uvod.json": {"content": "{\n  \"hero\": [\n    {\n      \"src\": \"img/nadvori.jpg\",\n      \"alt\": \"Nádvoří zámku s krytým pódiem\",\n      \"cap\": \"Nádvoří s pódiem, zastřešeným v roce 2019\"\n    },\n    {\n      \"src\": \"img/akce/2025-08-23-1.jpg\",\n      \"alt\": \"Noční prohlídka s pochodněmi\",\n      \"cap\": \"Hradozámecká noc, 23. 8. 2025\"\n    },\n    {\n      \"src\": \"img/h-2024-carodejnice.jpg\",\n      \"alt\": \"Děti u ohně při pálení čarodějnic\",\n      \"cap\": \"Pálení čarodějnic, 30. 4. 2024\"\n    },\n    {\n      \"src\": \"img/h-2024-kostymy.jpg\",\n      \"alt\": \"Lidé v historických kostýmech na nádvoří\",\n      \"cap\": \"Na nádvoří, 29. 6. 2024\"\n    },\n    {\n      \"src\": \"img/h-2025-country.jpg\",\n      \"alt\": \"Country tance pod pódiem\",\n      \"cap\": \"Pelmel muziky, 2. 8. 2025\"\n    },\n    {\n      \"src\": \"img/akce/2025-06-28-1.jpg\",\n      \"alt\": \"Historický den na nádvoří\",\n      \"cap\": \"Historický den, 28. 6. 2025\"\n    }\n  ],\n  \"roky\": [\n    {\n      \"rok\": \"2017\",\n      \"plakat\": \"img/plakaty/2017_zzt_program.jpg\"\n    },\n    {\n      \"rok\": \"2025\",\n      \"plakat\": \"img/plakaty/2025_sezona25.jpg\"\n    },\n    {\n      \"rok\": \"2026\",\n      \"plakat\": \"img/plakaty/2026_sezona26.jpg\"\n    }\n  ]\n}"}, "navsteva.json": {"content": "{\n  \"sezona\": \"Otevřené víkendy červenec–září\",\n  \"sezona_od\": 7,\n  \"sezona_do\": 9,\n  \"vstup_cas\": \"sobota a neděle 10–12 a 13–17 h\",\n  \"vstup_cena\": \"dobrovolné vstupné\",\n  \"prohlidka_cas\": \"sobota a neděle v 11, 14 a 16 h\",\n  \"prohlidka_cena\": \"50 Kč za osobu\",\n  \"kontakty\": [\n    {\"jmeno\": \"Pavla Vokurková\", \"funkce\": \"předsedkyně\", \"telefon\": \"+420 724 859 799\"},\n    {\"jmeno\": \"Alena Šlajerová\", \"funkce\": \"místopředsedkyně\", \"telefon\": \"+420 728 290 280\"}\n  ],\n  \"email\": \"zivyzamektouzim@email.cz\",\n  \"ucet\": \"2301034510/2010\"\n}\n"}, "suvenyry.json": {"content": "{\n  \"uvod\": \"Na akcích, o otevřených víkendech nebo poštou. Objednávky e-mailem.\",\n  \"polozky\": [\n    {\n      \"nazev\": \"Zámecký plecháček\",\n      \"popis\": \"Lehký a odolný plecháček s modrým okrajem, 360 ml.\",\n      \"cena\": \"300 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    },\n    {\n      \"nazev\": \"Tričko s logem\",\n      \"popis\": \"Bílé bavlněné tričko s černým logem Živého zámku.\",\n      \"cena\": \"300 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    },\n    {\n      \"nazev\": \"Mini model zámku\",\n      \"popis\": \"Kapesní model zámku Toužim v sáčku, číslovaný do sbírky.\",\n      \"cena\": \"110 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    },\n    {\n      \"nazev\": \"Placky a magnety\",\n      \"popis\": \"Malá placka 20 Kč, velká 40 Kč, magnet 50 Kč.\",\n      \"cena\": \"20–50 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    },\n    {\n      \"nazev\": \"Kniha Po stopách čarodějů\",\n      \"popis\": \"Pověsti o čarodějích a bylinkářích podél říčky Střely.\",\n      \"cena\": \"350 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    },\n    {\n      \"nazev\": \"Knížky Putování Hrocha\",\n      \"popis\": \"Čtyři knížky Petra Hrocha Bindera, výtěžek jde na zámek.\",\n      \"cena\": \"200 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    },\n    {\n      \"nazev\": \"Komiks o historii zámku\",\n      \"popis\": \"Vtipně o dějinách zámku od středověku po dnešek.\",\n      \"cena\": \"30 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    },\n    {\n      \"nazev\": \"Pohlednice\",\n      \"popis\": \"Čtyři motivy: fotografie zámku a tři malby z interiérů.\",\n      \"cena\": \"35 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    },\n    {\n      \"nazev\": \"Turistická známka č. 2864\",\n      \"popis\": \"K 555 letům města Toužim, limitováno 555 kusy.\",\n      \"cena\": \"55 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    },\n    {\n      \"nazev\": \"Pamětní mince 550 let\",\n      \"popis\": \"Starostříbro 50 Kč, starozlato 75 Kč, starobronz 100 Kč. Limitované série.\",\n      \"cena\": \"50–100 Kč\",\n      \"foto\": \"\",\n      \"skladem\": true\n    }\n  ]\n}"}}}};
